INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(635, 'koKR', 'Kryształ w górach', 'Odłamek pulsuje, gdy trzymasz go w dłoni...$B$BCzujesz bijące od niego błaganie, jakby ktoś próbował się z tobą porozumieć – ktoś, kto rozpaczliwie potrzebuje twojej pomocy.$B$BW twoim umyśle pojawia się wizja północnych gór Wyżyn Aratorskich i lśniącego kryształu, który wystaje tam z ziemi.$B$BCoś ciągnie cię w tamto miejsce.', 'Odnajdź kryształ ze swojej wizji.', '', '', '', '', '', '', 0),
(636, 'koKR', 'Legendy Ziemi <NYI>', 'Księga opowiada o księżniczce żywiołu, Myzrael, i o jej uwięzieniu głęboko pod Wyżynami Aratorskimi.$B$BWspomina też o ukrytej wychodni kryształów na wyżynach. Te kryształy, Odłamki Myzrael, są oknem do więzienia księżniczki.$B$BGdyby ktoś odważny odnalazł Odłamki Myzrael, to być może $gmógłby:mogłaby; z nią porozmawiać...', 'Odnajdź Odłamki Myzrael.', '', '', '', '', '', '', 0),
(638, 'koKR', 'Trollbane', 'Thoras Trollbane nie żyje, a Stromgard leży w gruzach, więc Vol\'jin polecił nam dołożyć wszelkich starań, by wykraść ludziom legendarny miecz Trol\'kalar. Posłużymy się nim w nadchodzących bitwach z trollami z Zul\'Gurub.$b$bZengu, jeden z naszych doświadczonych łowców, został wysłany do Młotogrodu w północno-wschodniej części Wyżyn Aratorskich, by dopilnować zdobycia miecza.', 'Udaj się do Młotogrodu na Wyżynach Aratorskich i porozmawiaj z Zengu.', '', '', '', '', '', '', 0),
(639, 'koKR', 'Symbol Stromu', 'W dawnych czasach trolle walczyły z Imperium Aratoru i z naszym najgroźniejszym przeciwnikiem, lordem Ignaeusem ze Stromu, zwanym Trollbane\'em. Ruszał do boju z mieczem Trol\'kalar – w ich dawnej mowie „pogromcą trolli”.$b$bAle dziś synowie Trollbane\'a są osłabieni, a ich twierdza legła w gruzach.$b$bMiecza strzeże kilka symboli, które rozdzielono między ocalałych ze Stromgardu – musimy je odzyskać.$b$bPierwszy zabrał Syndykat. Powinien go mieć jeden z ich ludzi w Stromgardzie.', 'Zdobądź symbol Stromu dla Zengu w Młotogrodzie.', '', 'Wróć do Zengu w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(640, 'koKR', 'Złamany symbol', 'Grobowca Thorasa Trollbane\'a strzegą trzy symbole – pierwszy z nich $godebrałeś:odebrałaś; Syndykatowi. Dwa pozostałe trudniej będzie zdobyć, bo ma je dobrze okopana milicja Stromgardu.$b$bSymbol Thoradina syn Thorasa, Galen, podzielił na pięć części i rozdał je obrońcom Stromgardu. Odzyskaj fragmenty i zanieś je Tor\'ganowi, trollowemu szamanowi – zdoła połączyć je w cały symbol.', 'Odbierz 5 fragmentów symbolu obrońcom Stromgardu i zanieś je Tor\'ganowi w Młotogrodzie.', '', 'Wróć do Tor\'gana w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(641, 'koKR', 'Symbol Thoradina', 'Odtworzenie przebiegło bez zarzutu. Symbolem można teraz otworzyć pieczęć na grobowcu Trollbane\'a. Zanieś go Zengu – z pewnością ma dla ciebie kolejne zadania.', 'Zanieś odtworzony symbol Thoradina Zengu w Młotogrodzie.', '', '', '', '', '', '', 0),
(642, 'koKR', 'Uwięziona księżniczka', 'Nazywam się Myzrael. Jestem księżniczką ziemi, a moi ciemięzcy, olbrzymy, uwięzili mnie głęboko pod Wyżynami Aratorskimi. Te kryształowe odłamki to jedyny sposób, bym mogła rozmawiać ze światem na powierzchni.$B$BPomóż mi, proszę. Sojusznicy olbrzymów, koboldy z Suchowąsów, mają podobny odłamek w swoim Wąwozie Suchowąsów, na wschodzie. Aby zasilić tamtą grupę kryształów, musisz zebrać od koboldów drobiny Myzrael i przyłożyć je do niej.$B$BBłagam cię, $N, pomóż mi!', 'Zbierz 12 drobin Myzrael, a następnie zanieś je do Opalizujących odłamków w Wąwozie Suchowąsów.', '', 'Odnajdź Opalizujące odłamki w Wąwozie Suchowąsów na Wyżynach Aratorskich.', '', '', '', '', 0),
(643, 'koKR', 'Symbol Aratoru', 'Choć trudno powiedzieć, że panują nad Stromgardem, a co dopiero nad całymi Wyżynami Aratorskimi, ludzki książę objeżdża okolicę z resztkami swojej kawalerii. Nie pojmuję, po co to robi, ale kto zrozumie, jak myślą ludzie, hm?$b$bMniejsza o jego powody – ważniejsze, że jeden z symboli dał porucznikowi Zewowi Męstwa, dowódcy swojej kawalerii. Odnajdź go i przynieś mi ten symbol.', 'Odzyskaj symbol Aratoru i zanieś go Zengu w Młotogrodzie.', '', 'Wróć do Zengu w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(644, 'koKR', 'Symbol Trollbane\'a', 'Ostatni z symboli potrzebnych do otwarcia grobowca Thorasa Trollbane\'a ma przy sobie jego syn. Przebywa w głębi Stromgardu, w kaplicy w dzielnicach zajętych przez milicję. Książę Galen jest dobrze chroniony, a i sam jest niezłym wojownikiem, więc to zadanie może się okazać bardzo trudne.', 'Zabij księcia Galena Trollbane\'a i zanieś symbol Trollbane\'a Zengu w Młotogrodzie.', '', 'Wróć do Zengu w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(645, 'koKR', 'Trol\'kalar', 'Co to? Cztery połączone symbole stopiły się w jeden. Nie ma wątpliwości, że zdoła on złamać osłony założone na grobowiec Trollbane\'a.$b$bSzczątki Trollbane\'a spoczywają w sanktuarium za kaplicą w Stromgardzie. Odzyskaj Trol\'kalar.', 'Wydobądź Trol\'kalar z grobowca Trollbane\'a w Stromgardzie.', '', '', '', '', '', '', 0),
(646, 'koKR', 'Trol\'kalar', 'Światło powoli gaśnie. Miecz Trol\'kalar, spoczywający w kamiennej pochwie, został uwolniony.', 'Dostarcz Trol\'kalar Zengu w Młotogrodzie.', '', '', '', '', '', '', 0),
(651, 'koKR', 'Kamienie Spętania', 'Na Wyżynach Aratorskich rozsiane są cztery Kamienie Spętania. To one więżą mnie pod ziemią.$B$BAby je otworzyć, musisz otworzyć najsilniejszy z nich: Kamień Wewnętrznego Spętania. A żeby to zrobić, musisz zdobyć klucze z trzech pozostałych.$B$BKamieni pilnują strażnicy, ale sprytem albo szczęściem zdołasz może ich przegnać.', 'Zdobądź płonący klucz, wzbierający klucz i grzmiący klucz z Kamienia Zachodniego Spętania, Kamienia Wschodniego Spętania i Kamienia Zewnętrznego Spętania.$B$BZanieś je do Kamienia Wewnętrznego Spętania.', '', 'Udaj się do Kamienia Wewnętrznego Spętania w Kręgu Wewnętrznego Spętania na Wyżynach Aratorskich.', '', '', '', '', 0),
(652, 'koKR', 'Rozbicie Zwornika', 'Otwarcie Kamieni Spętania zdjęło ze mnie wiele więzów, lecz wciąż trzyma mnie jeszcze jedna blokada. To Zwornik, który widzisz w tym kręgu kamieni. A klucz ma jeden z moich ciemięzców, kamienny obserwator Fozruk.$B$BMusisz zdobyć od Fozruka ten klucz – kamienni obserwatorzy nazywają go różdżką ładu – i otworzyć nim Zwornik.$B$B$N, tak wiele już dla mnie $gzrobiłeś:zrobiłaś;. Jeszcze tylko trochę... a moja wdzięczność wstrząśnie samymi fundamentami ziemi!', 'Odnajdź i zabij Fozruka. Zanieś różdżkę ładu do Zwornika na Wyżynach Aratorskich.', '', 'Wróć do Zwornika w Kręgu Wewnętrznego Spętania na Wyżynach Aratorskich.', '', '', '', '', 0),
(655, 'koKR', 'Młotogród', 'Wciąż widzę to wyraźnie, jakby to było wczoraj... Tyle lat bez nadziei, w drewnie i stali, które przykuwały mnie do tego strasznego miejsca. Aż wreszcie, wreszcie! Pojawił się wódz. Zgładziciel w zbroi czarnej jak noc, z wysoko uniesionym młotem bojowym.$b$bTo było... zbyt straszne... Że cios tchórza powalił naszego największego bohatera. Tamten natarł na niego konno od tyłu i przebił go kopią... Padłem na kolana. Jaka była nadzieja? Jaka jest nadzieja...', 'Porozmawiaj z Tor\'ganem w Młotogrodzie.', '', '', '', '', '', '', 0),
(656, 'koKR', 'Przywołanie księżniczki', 'Musisz pokonać Myzrael, zanim urośnie w siłę. Jeśli tego nie zrobisz, to gdy tylko zbierze dość mocy, rzuci wyzwanie swoim ciemięzcom! Niektórym się wydaje, że mogą ją kontrolować, ale skoro da się ją kontrolować, to po co olbrzymy w ogóle ją skuły??$B$BSzalona logika, co?$B$BAby ją pokonać, przywołaj ją przy Odłamkach Myzrael, gdzie $grozmawiałeś:rozmawiałaś; z nią po raz pierwszy. Pokonaj ją, zabierz jej niesamowite kajdany i przytwierdź je do Odłamków Myzrael.$B$BZrób to, a znów zostanie uwięziona.', 'Udaj się do Odłamków Myzrael, przywołaj ją i pokonaj.$B$BZabierz jej niesamowite kajdany i przytwierdź je do Odłamków Myzrael.', '', 'Wróć do Odłamków Myzrael w Zaziemiu.', '', '', '', '', 0),
(662, 'koKR', 'Wydobycie z głębin', 'O\'Breen wprowadził statki do zatoczki. Byliśmy pewni, że tu znajdziemy skarb. „Zwiastun” bezpiecznie przybił do brzegu, ale gdy zbliżały się „Dziewicze Szaleństwo” i „Duch Srebrzystego Boru”, zaczął się odpływ. Najdziwniejsza rzecz, jaką w życiu widziałem!$b$bTe dwa statki wpadły na coś... jakąś świątynię na rafie. Zatonęły tak szybko – prawdziwa tragedia.$b$bZanim odpłyniemy, musimy odzyskać ich dzienniki pokładowe i mapy. Nie możemy zostawić tych informacji wścibskim oczom!', 'Pierwszy oficer Nilzlix prosi cię o odzyskanie map i dzienników pokładowych z „Dziewiczego Szaleństwa” i „Ducha Srebrzystego Boru”.', '', 'Wróć do pierwszego oficera Nilzlixa w Zatoczce Faldira na Wyżynach Aratorskich.', '', '', '', '', 0),
(663, 'koKR', 'Ziemia na horyzoncie!', 'Lolo widzi kogoś malutkiego – to $r! Lolo zawsze czujny!$b$bWitaj w Zatoczce Faldira. Kapitan O\'Breen mówił, że zostaniemy tu tylko kilka godzin. Tyle, żeby zebrać skarb i wrócić do Łupieżczej Zatoki.$b$bAle Lolo myśli, że zostaniemy tu dużo dłużej. Straciliśmy dwa pozostałe statki z naszej formacji. Biedny „Duch Srebrzystego Boru” i biedne „Dziewicze Szaleństwo”. Teraz spoczywają na dnie morza!$b$bLolo radzi porozmawiać z kapitanem O\'Breenem, jeśli zamierzasz tu zostać.', 'Porozmawiaj z kapitanem O\'Breenem w Zatoczce Faldira na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(664, 'koKR', 'Topienie smutków', 'Ech, parszywe to życie. Powinienem teraz leżeć w wodnym grobie, a nie siedzieć przy ognisku i oddychać świeżym powietrzem.$b$bZałoga tak się starała ocalić moje piękne „Dziewicze Szaleństwo”. Dobre chłopaki, złote serca.$b$bO\'Breen bezpiecznie dotarł do brzegu, ale my nie mieliśmy tyle szczęścia. Morze po prostu się pod nami zapadło, przysięgam.$b$bW jednej chwili płyniemy, a w następnej wdziera się woda. I te bestie! Wybiły wszystkich ocalałych. Parszywe nagi. Straciłem przytomność i ocknąłem się tutaj, uratowany.$b$bChcę, żeby te bestie zdechły.', 'Kapitan Stalobrzuch z Zatoczki Faldira chce, żebyś $gzabił:zabiła; 10 najeźdźców Sztyletogrzbietych i 3 czarodziejki Sztyletogrzbietych.', '', 'Wróć do kapitana Stalobrzucha w Zatoczce Faldira na Wyżynach Aratorskich.', '', '', '', '', 0),
(665, 'koKR', 'Zatopiony skarb', 'Teraz, gdy jesteśmy pełnoprawnymi Łupieżcami Czarnej Wody, naszym zadaniem jest pomóc panu O\'Breenowi odnaleźć zaginiony elfi skarb.$b$bBez pomocy odnalezienie klejnotów w ciemnym morzu jest niemal niemożliwe. Doktor skonstruował gogle, które w tym pomogą. Trzeba je naładować energią z zaczarowanego kamienia w jaskini na wzgórzu.$b$bAle jaskinia jest przeklęta! Gdy tylko się zbliżamy, wpadamy w zasadzkę. Osłaniaj mnie, a przeniosę energię kamienia do gogli.', 'Odprowadź profesora Phizzlethorpe\'a do jaskini i z powrotem.', 'Osłaniaj profesora Phizzlethorpe\'a', 'Wróć do doktora Draxlegauge\'a w Zatoczce Faldira na Wyżynach Aratorskich.', '', '', '', '', 0),
(666, 'koKR', 'Zatopiony skarb', 'Skarb leży na dnie morza tak długo, że klejnoty zwapniały i pokryły się grubą warstwą kamienia. Ale moc zgromadzona w tych goglach pozwoli ci łatwo je namierzyć.$b$bOdrobina gnomiej pomysłowości czyni cuda!$b$bPożycz więc gogle poszukiwacza klejnotów, $N, i spróbuj zebrać trochę zaginionego skarbu dla kapitana O\'Breena.$b$bSam bym tam zanurkował, ale... eee... no cóż, mam ważne naukowe sprawy do załatwienia tu, na bezpiecznym, suchym lądzie... eee, no tak.', 'Doktor Draxlegauge z Zatoczki Faldira prosi, żebyś $gzebrał:zebrała; 10 elfich klejnotów i $goddał:oddała; gogle poszukiwacza klejnotów, gdy skończysz.', '', 'Wróć do doktora Draxlegauge\'a w Zatoczce Faldira na Wyżynach Aratorskich.', '', '', '', '', 0),
(667, 'koKR', 'Śmierć z głębin', 'Źle to wygląda. Zdaje się, że Sztyletogrzbieci zbierają się do ataku.$b$bNagi słyną z bezwzględności w boju. Będą atakować, dopóki nie zginę.$b$bNie cenię swojego życia wyżej niż życia moich ludzi, ale musisz pomóc mnie obronić. Bez mojej znajomości mórz załoga nie zdoła wrócić do Łupieżczej Zatoki.$b$bNagi nadejdą od morza. Musisz zostać tu ze mną na górze i odeprzeć atak. Obsadź działo i przepędź je.$b$bJesteś $ggotów:gotowa;, $N?', 'Chroń Shakesa O\'Breena podczas ataku.', 'Obroń Shakesa O\'Breena', 'Wróć do Shakesa O\'Breena w Zatoczce Faldira na Wyżynach Aratorskich.', '', '', '', '', 0),
(668, 'koKR', 'Zatopiony skarb', 'Nie każmy kapitanowi O\'Breenowi czekać. Będzie chciał zobaczyć te klejnoty na własne oczy. W końcu po to tu jesteśmy!$b$bA po kilku tygodniach zadawania się z tymi piratami profesor i ja zrozumieliśmy, że najgorsze dla naszego zdrowia byłoby dać się przyłapać z ich skarbem w rękach.$b$bMasz, $N, zanieś je O\'Breenowi.', 'Zanieś elfie klejnoty kapitanowi O\'Breenowi w Zatoczce Faldira na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(669, 'koKR', 'Zatopiony skarb', 'Mistrz floty Morski Róg zechce natychmiast usłyszeć o naszym znalezisku.$b$bAle jak widzisz, niełatwo nam się stąd wydostać. Nie dość, że woda stoi za nisko, to jeszcze te przeklęte stwory, którym przeszkodziliśmy, bacznie obserwują każdy nasz ruch.$b$bOddasz Łupieżcom Czarnej Wody wielką przysługę, jeśli dasz znać mistrzowi floty Morskiemu Rogowi w Łupieżczej Zatoce, że odnaleźliśmy skarb i pracujemy nad wydobyciem reszty. Zanieś mu tę próbkę jako dowód.', 'Zanieś próbkę elfiego klejnotu mistrzowi floty Morskiemu Rogowi w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(670, 'koKR', 'Zatopiony skarb', 'Słuchaj, $N, wyglądasz na $gposzukiwacza:poszukiwaczkę; przygód. Moja flota utknęła w Łupieżczej Zatoce, dopóki nie uzupełnimy zapasów.$b$bTu i za granicą szykują się poważne sprawy, a ja muszę przekazać ściśle tajną korespondencję Shakesowi O\'Breenowi, który utknął u wybrzeży Wyżyn Aratorskich.$b$bCzy mogę ci zaufać, że dostarczysz tę wiadomość bezpiecznie i w tajemnicy?', 'Dostarcz list Morskiego Rogu Shakesowi O\'Breenowi w Zatoczce Faldira na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(671, 'koKR', 'Plugawa magia', 'Wyczuwam w powietrzu coś dziwnego... coś, co burzy mi krew. Miałem swoje podejrzenia. Wyruszyłem, by znaleźć źródło niepokoju, i na zachodzie, we Dworze Północnej Zagrody, odkryłem ślady demonicznego przyzywania. Gdy się zbliżyłem, krew zaczęła we mnie wrzeć, a gniew rósł.$b$bNa ziemi dostrzegłem amulet z krwawnika, używany przy przyzywaniu demonów. Ten, który znalazłem, był jednak wyczerpany. Potrzebuję innego do zbadania, ale nie śmiem wracać do dworu. Przyniesiesz mi kilka?', 'Zdobądź 10 amuletów z krwawnika dla Tor\'gana w Młotogrodzie.', '', 'Wróć do Tor\'gana w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(672, 'koKR', 'Podnoszenie na duchu', 'Próbowaliśmy go tu zadomowić, rozweselić, opowiadaliśmy mu o naszym potężnym mieście Orgrimmar w Kalimdorze, ale nic go nie poruszyło.$b$bOpowieści o naszym młodym wodzu, Thrallu, który nosi zbroję i młot Orgrima... ale może... Może! Pokaz naszej na nowo odkrytej magii szamańskiej dałby mu nową nadzieję. Warto spróbować!$b$bMoglibyśmy zrobić dla niego jakiś mały przedmiot, tak... Przynieś mi trochę oczu raptorów, a zobaczę, co da się zrobić.', 'Zdobądź 10 oczu wyżynnego raptora od wyżynnych biegusów i wyżynnych tłukaczy dla Tor\'gana w Młotogrodzie.', '', 'Wróć do Tor\'gana w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(673, 'koKR', 'Plugawa magia', 'Nie mam wątpliwości, że w murach Stromgardu przebywa potężny czarnoksiężnik. Od czasu do czasu, za pomocą tajemnego magicznego reliktu, przyzywa całe zastępy strasznych demonów. Musimy odebrać mu źródło mocy.$b$bZnajdź czarnoksiężnika i zabij go. Przynieś mi każdy magiczny przedmiot, jaki przy nim znajdziesz, a postaram się go zniszczyć i dopilnuję, by jego moc już nigdy nie kaziła tej ziemi.', 'Zdobądź kulę z krwawnika Marez Cowl i zanieś ją Tor\'ganowi w Młotogrodzie.', '', 'Wróć do Tor\'gana w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(674, 'koKR', 'Podnoszenie na duchu', 'Masz, zanieś ten amulet Gor\'mulowi i zobacz, czy siła raptorów zdoła rozniecić płomień wojownika, który niegdyś płonął w jego żyłach.', 'Daj amulet ze szponu raptora Gor\'mulowi w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(675, 'koKR', 'Podnoszenie na duchu', '<Gor\'mul ciska amulet na ziemię.>$b$bTor\'gan cię przysłał, prawda? Phi! Nie rozumiem, czemu okazuje mi litość. Mnie litości odmówiono, gdy nie pozwolono mi zginąć w bitwie u boku mojego wodza. Okrutny cios zadał mi los...', 'Porozmawiaj z Tor\'ganem w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(677, 'koKR', 'Do broni!', 'Trolle Suchokorych i ogry Głazopięści z Wyżyn Aratorskich działają razem, by wygnać nas z tej ziemi, ale nie zginiemy z ich ani niczyjej innej ręki. Wybijemy ich i pokażemy im, że i my mamy tu dom.$B$BTrolle odwróciły się do nas plecami; ogry, gdybyśmy im pozwolili, zrobiłyby z nas jedzenie i posłanie – do tego nie dojdzie.$B$BAtak zaczniemy od trolli Suchokorych na południe stąd. Wybijaj ich całymi gromadami i wróć dopiero, gdy ich obozy spłyną krwią.', 'Zabij 10 miotaczy toporów Suchokorych, 10 łowców głów i 8 znachorów, a potem wróć do Druma Fela w placówce Młotogród.', '', 'Wróć do Druma Fela w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(678, 'koKR', 'Do broni!', 'Twoja siła jest oczywista, $N. Teraz zobaczymy, jak poradzisz sobie z prawdziwym wrogiem.$B$BGłazopięści mają leże na południowy zachód stąd, w stronę krasnoludzkiego mostu, i jeśli się nie mylę, tamtejsi mocarze i magowie będą dla ciebie większym wyzwaniem – dla nas dotąd byli.$B$BZabij ich tylu, ilu zdołasz, i przyjdź do mnie w ciele, gdy ci się powiedzie, albo w duchu, jeśli zawiedziesz. Tak czy inaczej, oddam cześć twojej wytrwałości w boju.', 'Zabij 10 osiłków Głazopięści i 4 magów Głazopięści, a potem wróć do Druma Fela w placówce Młotogród.', '', 'Wróć do Druma Fela w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(679, 'koKR', 'Do broni!', 'Łeb bestii jest gotów, by go odciąć... z wielką siłą, $N. Wszystko wskazuje na to, że zdołasz nam pomóc zadać ten ostatni, potężny cios. Przywódcy tych ataków założyli leże w ruinach Stromgardu, jaskrawym symbolu ludzkiej słabości.$B$BZnajdź i zabij władców Głazopięści oraz ich szamańskich popleczników, którzy chcą wygnać nas z tych ziem.', 'Zabij 7 szamanów Głazopięści i 3 władców Głazopięści, a potem wróć do Druma Fela w placówce Młotogród.', '', 'Wróć do Druma Fela w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(680, 'koKR', 'Prawdziwe zagrożenie', 'Dobrze służysz mojemu mężowi, $N, ale on nie wie, dlaczego Młotogród jest atakowany.$B$BOr\'Kalar, pionek Mug\'thola w Stromgardzie, pała do mojego męża gorącą nienawiścią i niczego nie pragnie bardziej niż jego śmierci – za to, że przed laty mój mąż go pokonał.$B$BMoje wróżby mówią, że Or\'Kalar zastawił na mojego męża pułapkę, dlatego ukryłam przed nim ślady obecności ogra.$B$BMój mąż popędziłby tam nierozważnie, gdyby dowiedział się, gdzie jest ogr, więc proszę cię o pomoc w zabiciu tej kreatury.', 'Zabij Or\'Kalara i zanieś jego głowę Korin Fel w placówce Młotogród.', '', 'Wróć do Korin Fel w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(681, 'koKR', 'Dwór Północnej Zagrody', 'Toczymy wojnę o Stromgard i przegrywamy. Ogry, Syndykat i my podzieliliśmy nasze niegdyś wielkie miasto, a każde stronnictwo walczy z pozostałymi w krwawym impasie.$B$BAle nasze siły topnieją, a wróg rośnie w siłę.$B$BPotrzebujemy pomocy z Południowego Brzegu, ale trudno o zaopatrzenie, dopóki Syndykat trzyma tereny między nami.$B$BIdź do bazy Syndykatu we Dworze Północnej Zagrody i wybij ich. Wtedy może nacisk na nasze konwoje zelżeje i więcej dostaw do nas dotrze.', 'Zabij 10 rozbójników Syndykatu i 6 najemników Syndykatu.$B$BWróć do kapitan Nials w Punkcie Schronienia.', '', 'Wróć do kapitan Nials w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(682, 'koKR', 'Odznaki Stromgardu', 'Syndykat w Stromgardzie walczy z naszym oddziałem milicji. Aby zachęcić hołotę do walki z naszymi, lepiej wyszkolonymi żołnierzami, przywódcy Syndykatu wyznaczyli nagrodę za naszych ludzi – płacą złotem za każdą odznakę Stromgardu zdjętą z zabitego milicjanta.$B$BChcemy odzyskać te odznaki – nie możemy pozwolić, by te rzezimieszki zabierały trofea naszym dzielnym poległym!$B$BWejdź na teren Stromgardu kontrolowany przez Syndykat i odbierz im nasze odznaki.', 'Przynieś 7 odznak Stromgardu kapitan Nials w Punkcie Schronienia.', '', 'Wróć do kapitan Nials w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(684, 'koKR', 'Poszukiwana! Marez Cowl', 'Wyznaczono nagrodę za głowę Marez Cowl, wysoko postawionej doradczyni i agentki Syndykatu. Ostatnio widziano ją na kontrolowanym przez Syndykat terenie Stromgardu.$B$BNagrodę można odebrać u kapitan Nials.$B$BUwaga: Marez to biegła i przebiegła czarnoksiężniczka, znana z konszachtów z demonami. Polując na nią, należy zachować najwyższą ostrożność.', 'Przynieś głowę Marez kapitan Nials w Punkcie Schronienia.', '', 'Wróć do kapitan Nials w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(685, 'koKR', 'Poszukiwani! Otto i Sokoli Herb', 'Milicja Stromgardu wyznaczyła nagrody za głowy lorda Sokolego Herbu i jego ochroniarza Otta. Sokoli Herb kieruje działaniami Syndykatu na Wyżynach Aratorskich, a jego śmierć poważnie by je zakłóciła.$B$BJego ochroniarz Otto nie jest celem strategicznym, ale to zażarty przeciwnik, który zabił dziesiątki naszych obrońców.$B$BNagrody można odebrać u kapitan Nials.', 'Przynieś głowę Otta i głowę Sokolego Herbu kapitan Nials w Punkcie Schronienia.', '', 'Wróć do kapitan Nials w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(688, 'koKR', 'Sprzymierzeńcy Myzrael', '<Myzrael przemawia.>$B$BWolna! JESTEM WOLNA! Mogę teraz gromadzić siły, ukryta przed moimi ciemięzcami. Gdyby teraz stanęli przeciwko mnie, z pewnością by mnie pokonali i znów uwięzili.$B$BAle z czasem zmierzę się z olbrzymami i pożałują, że mnie więzili!$B$BJesteś $gszlachetnym sprzymierzeńcem:szlachetną sprzymierzeńczynią;, $N. Z czasem znów będę potrzebować twojej pomocy. Gdy będę gotowa, przywołasz mnie na powierzchnię.$B$BPorozmawiaj z Zarukiem w Młotogrodzie. On wie, jak mnie przywołać.', 'Porozmawiaj z Zarukiem w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(691, 'koKR', 'Na wagę złota', 'Arcymag Malin przysłał mnie i Skuerta, żebyśmy zebrali dla niego odczynniki. Nie miałem pojęcia, jak zdobędę te rzeczy, ale skoro tu jesteś, chyba mój problem się rozwiązał.$B$BPotrzebuję kłów Suchokorych, sakiewek leczniczych Suchokorych i noża łowcy cieni.$B$BZdobędziesz je dla mnie? Suchokorzy żyją w południowo-wschodniej części Wyżyn Aratorskich.', 'Zdobądź 10 kłów Suchokorych, 4 sakiewki lecznicze Suchokorych i nóż łowcy cieni dla ucznia Krytena w Punkcie Schronienia.', '', 'Wróć do ucznia Krytena w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(693, 'koKR', 'Różdżka z pięści', 'Hej, $N. Wybacz, że wcześniej tak cię zbyłem... krótko. I nie, to nie żart o moim wzroście.$B$BUstaliłem, gdzie trafiła pierwsza rzecz Trelane\'a: ma ją Kor\'gresh w Sali Głazopięści. A sądząc po tym, jak ciskał lodowymi pociskami we własnych pobratymców, żeby trzymać ich w ryzach, musi być bliski rozgryzienia, jak korzystać ze wszystkich jej mocy.$B$BSala Głazopięści jest na południe stąd, a potem na wschód od Mostu Thandol. Znajdź ogra i odbierz mu tę różdżkę.$B$BA ja w tym czasie wymyślę, co zrobimy ze Stromgardem.', 'Odnajdź różdżkę inwokacji Trelane\'a i zanieś ją Skuertowi w Punkcie Schronienia.', '', 'Wróć do Skuerta w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(694, 'koKR', 'Zabezpieczenia Trelane\'a', '$GWypocząłeś:Wypoczęłaś;?$B$BOto nasz następny krok: wokół Wieży Aratoru w Stromgardzie roi się od ogrów. Musimy uruchomić zabezpieczenia wieży, jeśli masz mieć z nimi jakiekolwiek szanse i ujść z życiem, zdobywając te rzeczy. Do tego potrzebujemy kilku klejnotów, które upodobali sobie szamani Głazopięści. Zabrali je z wieży, ale długo ich nie zatrzymają.$B$BZdobądź jeden z tych klejnotów i zanieś go Krytenowi – zna zaklęcie, które je zaczaruje, żeby działały jak klucz.', 'Znajdź lazurowy agat i zanieś go uczniowi Krytenowi w Punkcie Schronienia.', '', 'Wróć do ucznia Krytena w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(695, 'koKR', 'Zaklęcie ucznia', 'Proszę, $N. Wystarczy przyłożyć klejnot do jednego z piedestałów u podstawy wieży, by uaktywnić jej zabezpieczenia. Użyj go, gdy będziesz $ggotów:gotowa; wejść do wieży i odnaleźć pozostałe rzeczy Trelane\'a.$B$BPowodzenia. Będę czekał na twój powrót tu, w obozie. Aha, i przed wyruszeniem porozmawiaj ze Skuertem. Przekaże ci resztę potrzebnych szczegółów.', 'Porozmawiaj ze Skuertem w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(696, 'koKR', 'Atak na wieżę', 'Oto, czego szukasz: filakteria Trelane\'a, kula Trelane\'a i żarzący agat Trelane\'a.$B$BWszystkie trzy powinny być w skrzyniach w wieży. Skrzynie otworzysz bez trudu; musisz tylko uważać na ogry.$B$BZabezpieczenia wieży same sobie z nimi nie poradzą; musisz mieć broń w pogotowiu. Jak te ogry się dowiedzą, że tam jesteś i je okradasz, na pewno dadzą ci popalić.$B$BUważaj na siebie i powodzenia.', 'Odnajdź filakterię Trelane\'a, kulę Trelane\'a i żarzący agat Trelane\'a, a potem zanieś je Skuertowi w Punkcie Schronienia.', '', 'Wróć do Skuerta w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(701, 'koKR', 'Przebiegłość raptora', 'Z kilkoma dodatkowymi przedmiotami zdołam stworzyć coś, co natchnie Gor\'mula przebiegłością raptora! Gdy moc raptora popłynie w jego żyłach, Gor\'mul pozna naszą nową potęgę i odnajdzie w sobie uśpionego wojownika!$b$bDo wykonania przedmiotu i zaklęcia potrzebuję serc raptorów.', 'Zdobądź 12 serc raptora z wyżynnych łowców mięsa dla Tor\'gana.', '', 'Wróć do Tor\'gana w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(702, 'koKR', 'Przebiegłość raptora', 'Weź tę kulę i użyj jej energii, by dać Gor\'mulowi esencję raptora. To z pewnością ożywi jego ducha i nada jego życiu nowy cel. Gdy wróci do siebie, wyjaśnimy mu, w jakim położeniu jest teraz Horda, a w naszych nieustających bitwach wesprze nas wielki wojownik.', 'Daj Kulę Tor\'gana Gor\'mulowi w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(847, 'koKR', 'Przebiegłość raptora', 'Ta... ta moc... Czy to moc szamanów, którą Tor\'gan próbował mi pokazać? Muszę przyznać, że jest ciekawa. Powiedz Tor\'ganowi, że mnie przekonał... na razie. Wysłucham, co ma do powiedzenia.', 'Porozmawiaj z Tor\'ganem w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', '', '', 0),
(5144, 'koKR', 'Garbarstwo żywiołów', 'Znam się na garbarstwie żywiołów i jeśli zechcesz otworzyć umysł na wyższe moce materii, podzielę się z tobą wszystkim, czego można się nauczyć.$B$BWiedz jednak, $N: wybierając tę ścieżkę, zgadzasz się nigdy nie uczyć garbarstwa smoczołuskiego ani plemiennego – można praktykować tylko jedną z tych trzech sztuk. Co więcej, potrzebuję wyraźnego dowodu, że żyjesz w zgodzie z żywiołami natury. Dlatego przynieś mi najczystsze esencje ognia, wody, ziemi i wiatru.', 'Przynieś 2 serca ognia, 2 kule wody, 2 rdzenie ziemi i 2 oddechy wiatru Sarah Tanner w Płonącym Wąwozie.$B$BUkończenie tego zadania da ci dostęp do sztuki garbarstwa żywiołów.$B$BUkończenie tego zadania uniemożliwi ci naukę garbarstwa smoczołuskiego i garbarstwa plemiennego. Zanim to zrobisz, upewnij się, że to ścieżka, którą chcesz podążać.', '', 'Wróć do Sarah Tanner w Obozie Garbarzy w Płonącym Wąwozie.', '', '', '', '', 0),
(5146, 'koKR', 'Garbarstwo żywiołów', 'Znam się na garbarstwie żywiołów i jeśli zechcesz otworzyć umysł na wyższe moce materii, podzielę się z tobą wszystkim, czego można się nauczyć.$B$BWiedz jednak, $N: wybierając tę ścieżkę, zgadzasz się nigdy nie uczyć garbarstwa smoczołuskiego ani plemiennego – można praktykować tylko jedną z tych trzech sztuk. Co więcej, potrzebuję wyraźnego dowodu, że żyjesz w zgodzie z żywiołami natury. Dlatego przynieś mi najczystsze esencje ognia, wody, ziemi i wiatru.', 'Przynieś 2 serca ognia, 2 kule wody, 2 rdzenie ziemi i 2 oddechy wiatru Brumnowi Zimowemu Kopytu na Wyżynach Aratorskich.$B$BUkończenie tego zadania da ci dostęp do sztuki garbarstwa żywiołów.$B$BUkończenie tego zadania uniemożliwi ci naukę garbarstwa smoczołuskiego i garbarstwa plemiennego. Zanim to zrobisz, upewnij się, że to ścieżka, którą chcesz podążać.', '', 'Wróć do Brumna Zimowego Kopyta w Boulder\'gor na Wyżynach Aratorskich.', '', '', '', '', 0),
(6622, 'koKR', 'Segregacja rannych', 'Dzień dobry, $gdoktorze:pani doktor;. Dziś po południu sprawdzimy, czy umiesz właściwie segregować rannych. Jeśli zdasz egzamin, dołączysz do prestiżowych szeregów Oddziału Urazowego Hordy.$B$BA teraz uwaga! Najpierw trzeba zająć się rannymi w stanie krytycznym. Po nich – ciężko rannymi. Lżej rannymi należy zająć się na końcu. Aby zdać egzamin, musisz uratować 15 pacjentów. Oblejesz, jeśli podczas segregacji umrze 6 twoich pacjentów.$B$BBandaże polowe dostaniesz na miejscu.$B$BPowodzenia, $gdoktorze:pani doktor;.$B', 'Ratuj pacjentów, opatrując ich rany bandażami polowymi. Musisz uratować 15 pacjentów, zanim 6 z nich umrze od odniesionych ran.$B$BPamiętaj o kolejności segregacji! Żołnierze w stanie krytycznym umierają najszybciej, a po nich ciężko ranni żołnierze. Ranni żołnierze umierają najwolniej i należy ich ratować DOPIERO PO opatrzeniu żołnierzy w stanie krytycznym i ciężko rannych.', 'Uratowano 15 pacjentów!', 'Wróć do doktora Gregory\'ego Victora w Młotogrodzie na Wyżynach Aratorskich.', '', '', '', '', 0),
(6624, 'koKR', 'Segregacja rannych', 'Dzień dobry, $gdoktorze:pani doktor;. Dziś po południu sprawdzimy, czy umiesz właściwie segregować rannych. Jeśli zdasz egzamin, dołączysz do prestiżowych szeregów Oddziału Urazowego Przymierza.$B$BA teraz uwaga! Najpierw trzeba zająć się rannymi w stanie krytycznym. Po nich – ciężko rannymi. Lżej rannymi należy zająć się na końcu. Aby zdać egzamin, musisz uratować 15 pacjentów. Oblejesz, jeśli podczas segregacji umrze 6 twoich pacjentów.$B$BPowodzenia, $gdoktorze:pani doktor;.$B', 'Ratuj pacjentów, opatrując ich rany bandażami polowymi. Musisz uratować 15 pacjentów, zanim 6 z nich umrze od odniesionych ran.$B$BPamiętaj o kolejności segregacji! Żołnierze w stanie krytycznym umierają najszybciej, a po nich ciężko ranni żołnierze. Ranni żołnierze umierają najwolniej i należy ich ratować DOPIERO PO opatrzeniu żołnierzy w stanie krytycznym i ciężko rannych.', 'Uratowano 15 pacjentów!', 'Wróć do doktora Gustafa VanHowzena na Wyspie Theramore na Pyłowym Bagnisku.', '', '', '', '', 0),
(8081, 'koKR', 'Więcej skrzyń zasobów', '', '', '', 'Wróć do sierżant Maclear na Wyżynach Aratorskich.', '', '', '', '', 0),
(8105, 'koKR', 'Bitwa o Kotlinę Aratorską!', '$N, bitwa o Kotlinę Aratorską to walka o zasoby i terytorium. Kluczowe punkty tego obszaru trzeba utrzymać i eksploatować, by zaopatrywać nasze siły w tak potrzebne surowce i zapasy. Rozkazuję ci zaatakować punkty położone najdalej od naszej bazy w Kotlinie Aratorskiej.$B$BZaatakuj farmę, kopalnię, tartak i kuźnię, gdy będą w rękach wroga. Znajdź sztandar wroga i zerwij go z masztu!$B$BGdy zrobisz to we wszystkich czterech punktach, wróć do mnie.', 'Zaatakuj kopalnię, tartak, kuźnię i farmę, a następnie wróć do feldmarszałka Oslighta w Punkcie Schronienia.', '', 'Wróć do feldmarszałka Oslighta w Punkcie Schronienia na Wyżynach Aratorskich.', 'Zaatakowana kopalnia', 'Zaatakowany tartak', 'Zaatakowana kuźnia', 'Zaatakowana farma', 0),
(8114, 'koKR', 'Kontroluj cztery bazy', '$N, $gzaniosłeś:zaniosłaś; bitwę o Kotlinę Aratorską do naszych wrogów i $gzdobyłeś:zdobyłaś; na tym polu bitwy wielkie zaszczyty. $GPokazałeś:Pokazałaś; nam swoją wartość jako $c, a wrogom – że nie ugniemy się przed ich nikczemnością!$B$BPonieważ $gdowiodłeś:dowiodłaś; swojej wartości, mam dla ciebie trudne zadanie. Chcę, żebyś $gzdobył:zdobyła; i $gutrzymał:utrzymała; co najmniej cztery bazy w Kotlinie Aratorskiej. Jeśli ci się uda, nie tylko zabezpieczymy kluczowe zasoby, ale też pokażemy Hordzie naszą przewagę!$B$BIdź, $N, i powodzenia.', 'Wejdź do Kotliny Aratorskiej, zdobądź i utrzymaj jednocześnie cztery bazy, a następnie wróć do feldmarszałka Oslighta w Punkcie Schronienia.', 'Kontroluj cztery bazy.', 'Wróć do feldmarszałka Oslighta w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(8115, 'koKR', 'Kontroluj pięć baz', '$N, walka o zasoby Kotliny Aratorskiej to krwawe przedsięwzięcie. Twoje usługi dla Ligi Aratoru są równie potrzebne, co doceniane.$B$BI mamy dla ciebie jeszcze jedno zadanie.$B$BLiga chce przypuścić jeden potężny szturm na Plugawicieli okupujących Kotlinę Aratorską. Chcemy ich wyprzeć z każdego strategicznego punktu na polu bitwy!$B$BNie będzie łatwo, ale jeśli ktoś może tego dokonać, to właśnie ty.', 'Kontroluj jednocześnie 5 baz w Kotlinie Aratorskiej, a następnie wróć do feldmarszałka Oslighta w Punkcie Schronienia.', 'Zdobądź pięć baz.', 'Wróć do feldmarszałka Oslighta w Punkcie Schronienia na Wyżynach Aratorskich.', '', '', '', '', 0),
(8120, 'koKR', 'Bitwa o Kotlinę Aratorską!', 'Jak z pewnością $gsłyszałeś:słyszałaś;, Liga Aratoru wysyła do Kotliny Aratorskiej liczne oddziały. Ci głupcy z Przymierza, spragnieni żywności i zapasów, chcą zająć tamtejsze bogate zasoby i nad nimi zapanować. Musimy im pokazać, że Arator już nigdy nie będzie domem ludzi!$B$BUdaj się do Kotliny Aratorskiej i zaatakuj kopalnię, tartak, kuźnię i stajnię. Zerwij sztandary wroga i ogłoś te tereny ziemiami Hordy.$B$BIdź, $N. Wróć do mnie z raportem, gdy wykonasz to zadanie.', 'Zaatakuj kopalnię, tartak, kuźnię i stajnię w Kotlinie Aratorskiej, a następnie wróć do mistrzyni śmierci Dwire w Młotogrodzie.', '', 'Wróć do mistrzyni śmierci Dwire w Kręgu Wschodniego Spętania na Wyżynach Aratorskich.', 'Zaatakowana kopalnia', 'Zaatakowany tartak', 'Zaatakowana kuźnia', 'Zaatakowana stajnia', 0),
(8121, 'koKR', 'Zdobądź cztery bazy', '$N, gdy trwają zażarte walki o Kotlinę Aratorską, wieści o twoich czynach dotarły do wielu uszu. Cieszysz się wśród nas wielkim uznaniem, co daje mi pewność, że wykonasz misję, którą mam teraz dla ciebie.$B$BPora wysłać wiadomość Lidze Aratoru. Musimy im pokazać, że ich zdobycze w Kotlinie Aratorskiej są niepewne i łatwo je stracić. Pokażemy im to, utrzymując jednocześnie cztery strategiczne punkty w Kotlinie Aratorskiej.$B$BJeśli ci się to uda, $N, zyskasz wielki szacunek wśród Plugawicieli.', 'Utrzymaj jednocześnie cztery bazy w Kotlinie Aratorskiej, a następnie wróć do mistrzyni śmierci Dwire w Młotogrodzie.', 'Utrzymaj cztery bazy.', 'Wróć do mistrzyni śmierci Dwire w Kręgu Wschodniego Spętania na Wyżynach Aratorskich.', '', '', '', '', 0),
(8122, 'koKR', 'Zdobądź pięć baz', 'Trudno to dostrzec, gdy tkwimy tak głęboko w tym konflikcie, ale nasi szpiedzy donoszą, że determinacja Ligi Aratoru słabnie. Musimy wykorzystać tę okazję i zadać im brutalny cios! Wróć do Kotliny Aratorskiej i rzuć się na naszych wrogów. Przeklinaj ich, zabijaj i zdobądź wszystkie pięć strategicznych baz! Niech ich żołnierze uciekają z linii frontu z krzykiem, brocząc krwią, z opowieściami o twoim okrucieństwie na skomlących ustach.$B$BZrób to, a odniesiesz wielkie zwycięstwo dla Plugawicieli.', 'Utrzymaj jednocześnie pięć baz w Kotlinie Aratorskiej, a następnie wróć do mistrzyni śmierci Dwire w Młotogrodzie.', 'Utrzymaj pięć baz.', 'Wróć do mistrzyni śmierci Dwire w Kręgu Wschodniego Spętania na Wyżynach Aratorskich.', '', '', '', '', 0),
(8124, 'koKR', 'Więcej skrzyń zasobów', '', '', '', 'Wróć do tropiciela śmierci Mortisa na Wyżynach Aratorskich.', '', '', '', '', 0),
(8157, 'koKR', 'Więcej skrzyń zasobów', '', '', '', 'Wróć do sierżant Maclear na Wyżynach Aratorskich.', '', '', '', '', 0),
(8158, 'koKR', 'Więcej skrzyń zasobów', '', '', '', 'Wróć do sierżant Maclear na Wyżynach Aratorskich.', '', '', '', '', 0),
(8159, 'koKR', 'Więcej skrzyń zasobów', '', '', '', 'Wróć do sierżant Maclear na Wyżynach Aratorskich.', '', '', '', '', 0),
(8163, 'koKR', 'Więcej skrzyń zasobów', '', '', '', 'Wróć do tropiciela śmierci Mortisa na Wyżynach Aratorskich.', '', '', '', '', 0),
(8164, 'koKR', 'Więcej skrzyń zasobów', '', '', '', 'Wróć do tropiciela śmierci Mortisa na Wyżynach Aratorskich.', '', '', '', '', 0),
(8165, 'koKR', 'Więcej skrzyń zasobów', '', '', '', 'Wróć do tropiciela śmierci Mortisa na Wyżynach Aratorskich.', '', '', '', '', 0),
(8166, 'koKR', 'Bitwa o Kotlinę Aratorską!', '$N, bitwa o Kotlinę Aratorską to walka o zasoby i terytorium. Kluczowe punkty tego obszaru trzeba utrzymać i eksploatować, by zaopatrywać nasze siły w tak potrzebne surowce i zapasy. Rozkazuję ci zaatakować punkty położone najdalej od naszej bazy w Kotlinie Aratorskiej.$B$BZaatakuj farmę, kopalnię, tartak i kuźnię, gdy będą w rękach wroga. Znajdź sztandar wroga i zerwij go z masztu!$B$BGdy zrobisz to we wszystkich czterech punktach, wróć do mnie.', 'Zaatakuj kopalnię, tartak, kuźnię i farmę, a następnie wróć do feldmarszałka Oslighta w Punkcie Schronienia.', '', 'Wróć do feldmarszałka Oslighta w Punkcie Schronienia na Wyżynach Aratorskich.', 'Zaatakowana kopalnia', 'Zaatakowany tartak', 'Zaatakowana kuźnia', 'Zaatakowana farma', 0),
(8167, 'koKR', 'Bitwa o Kotlinę Aratorską!', '$N, bitwa o Kotlinę Aratorską to walka o zasoby i terytorium. Kluczowe punkty tego obszaru trzeba utrzymać i eksploatować, by zaopatrywać nasze siły w tak potrzebne surowce i zapasy. Rozkazuję ci zaatakować punkty położone najdalej od naszej bazy w Kotlinie Aratorskiej.$B$BZaatakuj farmę, kopalnię, tartak i kuźnię, gdy będą w rękach wroga. Znajdź sztandar wroga i zerwij go z masztu!$B$BGdy zrobisz to we wszystkich czterech punktach, wróć do mnie.', 'Zaatakuj kopalnię, tartak, kuźnię i farmę, a następnie wróć do feldmarszałka Oslighta w Punkcie Schronienia.', '', 'Wróć do feldmarszałka Oslighta w Punkcie Schronienia na Wyżynach Aratorskich.', 'Zaatakowana kopalnia', 'Zaatakowany tartak', 'Zaatakowana kuźnia', 'Zaatakowana farma', 0),
