INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(635, 'koKR', 'Kryształ pulsuje, jakby uwięziono w nim żywą siłę.', 0),
(638, 'koKR', 'Jak leci, $N? Zadanie, które postawił przed nami Vol\'jin, będzie trudne, więc każda pomoc się przyda – ba, będzie niezbędna.', 0),
(639, 'koKR', 'Świetnie, mon. To dobry początek zbierania symboli, których potrzebujemy, by wydobyć Trol\'kalar z grobowca Trollbane\'a.', 0),
(640, 'koKR', 'Ach, chcesz, żebym odtworzył ten symbol? To nie powinno być zbyt trudne... wszystkie części chyba są na miejscu, a magiczną strukturę łatwo będzie odbudować.$b$bLepiej zamknij oczy.', 0),
(641, 'koKR', 'Połowa drogi za nami – niedługo wydobędziemy Trol\'kalar z grobowca Trollbane\'a. Nie wiemy dokładnie, gdzie jest trzeci symbol, bo jego posiadacze sporo krążą po Wyżynach Aratorskich, ale wierzę, że go znajdziesz.', 0),
(642, 'koKR', 'Ach! $GAktywowałeś:Aktywowałaś; te odłamki. Już czuję się bardziej sobą!$b$bNiestety wciąż daleko mi do wolności...', 0),
(643, 'koKR', 'Utrata dowódcy kawalerii będzie dla obrońców Stromgardu dotkliwym ciosem. Co więcej, dzieli nas już tylko jeden symbol od tego, by Trol\'kalar był nasz.', 0),
(644, 'koKR', 'Cóż to za dzień, $N. Krew Trollbane\'ów nie będzie już prześladować mojego ludu, a symbole potrzebne do zdobycia Trol\'kalar są w naszych rękach. Wkrótce, już niedługo, uderzymy na znienawidzone trolle z Zul\'Gurub.', 0),
(645, 'koKR', 'Gdy dopasowujesz linie na płycie grobowca Trollbane\'a do lśniących linii symbolu Ignaeusa, błysk światła pochłania symbol, a kamienne dłonie wypuszczają z uścisku legendarny miecz Trol\'kalar.', 0),
(646, 'koKR', 'Przez pokolenia trolle cierpiały od sił Stromu i Aratoru. Teraz ich największa broń jest w naszych rękach. Koniec z mozolnym przedzieraniem się przez parne lasy Zul\'Gurub.$b$bBardzo nam $gpomogłeś:pomogłaś;, $N, a trolle z plemienia Mrocznej Włóczni mają wobec ciebie dług.$b$bDopilnuję, by miecz trafił do Nimboyi w Grom\'gol.', 0),
(651, 'koKR', '<Myzrael przemawia przez kamień.>$b$bUdało ci się! $GOtworzyłeś:Otworzyłaś; Kamienie Spętania! Czuję, jak moje kajdany słabną, a wolność jest coraz bliżej.$b$b$GSzlachetny:Szlachetna; z ciebie $c, $N. $GMój wybawca:Moja wybawczyni;!', 0),
(652, 'koKR', 'Wkładasz różdżkę w zwornik. Czujesz pod stopami drżenie...', 0),
(655, 'koKR', 'Ach, mówisz o Gor\'mulu. Tak, z tego, co mówi, wynika, że nigdy nie otrząsnął się po śmierci Zgładziciela.$B$BGor\'mul był tu więźniem, gdy Thrall i Orgrim walczyli o uwolnienie obozu, ale kiedy ziemia zadrżała, a nasi bracia uciekli, on został. Całymi latami błąkał się samotnie, bez celu i bez nadziei, dopóki nie wróciliśmy i nie założyliśmy tu Młotogrodu.', 0),
(656, 'koKR', 'Gdy niesamowite kajdany oplatają Odłamki, z głębi dobiega nieludzkie zawodzenie. Po krzyku rozlega się ryk.$b$bOdłamki Myzrael nie budzą już poczucia ciepła i bezpieczeństwa jak dawniej. Teraz pulsują jawną groźbą... jakby to, co pod nimi spoczywa, żywiło wrogość wobec świata na powierzchni.', 0),
(662, 'koKR', 'Świadomość, że te informacje są bezpieczne, przyniesie nieco ulgi dowództwu w Łupieżczej Zatoce. Dobra robota, $N.', 0),
(663, 'koKR', 'Ahoj!$b$bStraszna jatka. Morski Róg odbierze mi statek, jak się dowie, co tu zaszło.$b$bJedno z urządzeń profesora wskazało, że zaginiony skarb jest blisko tej zatoczki. Wprowadziłem „Zwiastuna” do przystani i dałem sygnał „Duchowi Srebrzystego Boru” i „Dziewiczemu Szaleństwu”, żeby zrobiły to samo.$b$bWtedy morze zadudniło. Nastąpił odpływ i oba statki roztrzaskały się o rafę.$b$bTo nie jest zwykła rafa. Coś tam na dole jest...$b$bPomóż mojej załodze, a sowicie cię wynagrodzę.', 0),
(664, 'koKR', 'Dobra robota, $N.$b$bTe szumowiny dostały, na co zasłużyły. Nic mi nie zwróci statku ani załogi, ale śmierć tych nag daje mi trochę pociechy.', 0),
(665, 'koKR', 'Gogle działają teraz doskonale! Dobra robota, $N.', 0),
(666, 'koKR', 'Znakomicie, $N! Kapitan będzie bardzo zadowolony! A poczekaj tylko, aż wieść dotrze do mistrza floty Morskiego Rogu!', 0),
(667, 'koKR', 'Przetrwaliśmy atak!$b$bBez ciebie by się nie udało, $N.$b$bWypływamy, gdy tylko przyjdzie przypływ. Gdybyś nie $gbył tak obiecującym bohaterem:była tak obiecującą bohaterką;, zaproponowałbym ci miejsce w mojej załodze. Ale widzę, że masz grubsze ryby do złowienia.$b$bNawet jeśli z ciebie $gcherlawy:cherlawa; $r...', 0),
(668, 'koKR', 'Czyli te małe gnomy jednak się przydały? Wiedziałem, że nie bez powodu trzymamy przy sobie tych kurdupli!', 0),
(669, 'koKR', 'Ach, na starym dobrym Shakesie O\'Breenie zawsze można polegać! Wiedziałem, że to właściwy kapitan do tej misji!', 0),
(670, 'koKR', 'Dziękuję, że $gpodjąłeś:podjęłaś; się tak długiej i niebezpiecznej podróży. Masz wdzięczność Łupieżców Czarnej Wody.', 0),
(671, 'koKR', 'Ustalenie prawdziwych zamiarów Syndykatu zajmie mi trochę czasu, ale ich oczywiste powiązania z mroczną, demoniczną magią budzą mój niepokój. Powiem ci, gdy dowiem się więcej.', 0),
(672, 'koKR', 'Świetnie. Duchy raptorów, od których pochodzą te oczy, użyczą siły temu, kto będzie nosił ten amulet.', 0),
(673, 'koKR', 'Moje niespokojne noce zmienią się w spokojny sen, gdy zniszczę tę kulę. Dziękuję, $N. To mrożące krew w żyłach przypomnienie strasznej władzy, jaką demony miały nad orkami, zanim Piekłorycz uwolnił ich od klątwy.', 0),
(674, 'koKR', 'Co to? Wypolerowana kość. Na co mi wypolerowana kość? Czy błyskotka przywróci Hordzie dawną chwałę?', 0),
(675, 'koKR', 'Widzę, że się nie udało. Mimo to czuję, że pokazanie mu mocy szamanów w końcu przywróci Gor\'mulowi dawną dumę. Moc amuletu była zbyt słaba, by ukazać mu naszą nowo odkrytą potęgę.', 0),
(677, 'koKR', 'Na twoim odzieniu widać ślady wojny, a z czoła spływa ci pot. Dobrze, bardzo dobrze.', 0),
(678, 'koKR', 'Jesteś $gsilny:silna; jak kodo, a twoja żądza walki przynosi chlubę twojemu ludowi.', 0),
(679, 'koKR', 'Przynosisz chlubę swojemu ludowi, $N. Zagrożenie znacznie zmalało i jestem pewien, że zaczniemy się tu, na wyżynach, rozwijać.', 0),
(680, 'koKR', '$GOddałeś:Oddałaś; mi wielką przysługę, $N. Wiedz, że dzięki twoim czynom życie mojego męża i bezpieczeństwo Młotogrodu są ocalone na kolejny dzień. Przyjmij to w nagrodę za odwagę.', 0),
(681, 'koKR', 'Bardzo dobrze, $N. Po śmierci tych członków Syndykatu łatwiej nam będzie dostawać zaopatrzenie z Południowego Brzegu.$b$bMoże nasza sprawa nie jest jeszcze stracona.', 0),
(682, 'koKR', 'Dziękuję, $N. Powiadomimy rodziny tych żołnierzy, że polegli w walce.$b$bTo będą ponure wieści, ale lepsze to niż niepewność co do losu zaginionej bliskiej osoby.', 0),
(684, 'koKR', '$GZabiłeś:Zabiłaś; Marez Cowl? Dobra robota, $N. Naprawdę świetna robota!$b$bMarez była postrachem naszych obrońców w Stromgardzie, a podobno pośredniczyła między Syndykatem a jakąś inną, mroczniejszą siłą. Cieszymy się, że już nie zwróci swoich mocy przeciwko nam.', 0),
(685, 'koKR', 'Sokoli Herb i Otto? Wspaniale!$b$bOto twoja nagroda, $N. Z przyjemnością ją wypłacam.', 0),
(688, 'koKR', 'Witaj, $N. Pani zapowiedziała twoje przybycie, a skoro mamy sprowadzić ją z powrotem na powierzchnię, czeka nas wiele do omówienia...', 0),
(691, 'koKR', 'Niesamowite! Rozumiem, czemu Malin poprosił cię, żebyś do nas $gdołączył:dołączyła; – świetna robota!$B$BW tym tempie ja i Skuerto w mig wrócimy do Wichrogrodu.$B$BZdaje się, że mój krasnoludzki towarzysz wrócił ze zwiadu w Sali Głazopięści; porozmawiaj z nim, gdy będziesz $ggotów:gotowa;.$B$BWyglądało na to, że miał małą potyczkę z ogrami. Tylko mu o tym nie wspominaj; jest bardzo drażliwy na punkcie krytyki swoich umiejętności zwiadowczych.', 0),
(693, 'koKR', 'Świetnie, $N. Jedna rzecz z głowy, zostały trzy, jak wynika z mojej listy. Pozostałe trzy są w Stromgardzie.$B$BOdpocznij i zbierz siły – następny etap mojego planu będzie wymagał nieco więcej czasu i wysiłku. Wróć do mnie, jak zjesz coś ciepłego i odpoczniesz.', 0),
(694, 'koKR', 'Zadziwiasz mnie, $N. Znów świetna robota.$B$BDaj mi chwilę na rzucenie odpowiedniego zaklęcia na klejnot, a będziesz $ggotów:gotowa;.', 0),
(695, 'koKR', 'Dobrze, dobrze.$b$bJeśli nic nas już nie zatrzyma, to może zaczynamy?', 0),
(696, 'koKR', 'Malin nie mógł przysłać nam do pomocy nikogo godniejszego, $N. $GSpisałeś:Spisałaś; się wspaniale!$B$BUcieszy się, widząc, jak ogromnym sukcesem okazała się nasza misja.', 0),
(701, 'koKR', 'Tak, te nadadzą się doskonale. Przeniosę ich moc i ducha raptorów do tej kuli. Kula ta natchnie Gor\'mula ognistą siłą i sprytem raptora.', 0),
(702, 'koKR', 'Przynajmniej tym razem przynosisz mi coś ciekawego. Bije od tego dziwna moc...', 0),
(847, 'koKR', 'Gdy zaklęcie przestanie działać, porozmawiam z Gor\'mulem. Dziękuję ci za pomoc w przywróceniu Gor\'mula do krainy żywych. Nie wątpię, że i on jest ci ogromnie wdzięczny.', 0),
(5144, 'koKR', '$GZwiązałeś:Związałaś; swój los z żywiołami, a one cię przyjmują. Gdy zakończę twoje szkolenie, będziesz $gmógł:mogła; tworzyć najwspanialsze skórzane stroje.$B$BJeśli zechcesz w przyszłości szkolić się w tej sztuce, po prostu ze mną porozmawiaj, a udostępnię ci całą wiedzę, której jeszcze nie $gprzyswoiłeś:przyswoiłaś;.', 0),
(5146, 'koKR', '$GZwiązałeś:Związałaś; swój los z żywiołami, a one cię przyjmują. Gdy zakończę twoje szkolenie, będziesz $gmógł:mogła; tworzyć najwspanialsze skórzane stroje.$B$BJeśli zechcesz w przyszłości szkolić się w tej sztuce, po prostu ze mną porozmawiaj, a udostępnię ci całą wiedzę, której jeszcze nie $gprzyswoiłeś:przyswoiłaś;.', 0),
(6622, 'koKR', 'Witaj w Oddziale Urazowym Hordy, $gdoktorze:pani doktor; $N.', 0),
(8081, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od piechura po feldmarszałka.', 0),
(8105, 'koKR', 'Dotarły do mnie wieści o twoich wyczynach w Kotlinie Aratorskiej, $N. Dobra robota! Skoro do naszej walki przyłączają się tacy jak ty, wierzę, że pewnego dnia odzyskamy nasze ojczyste ziemie.', 0),
(8114, 'koKR', 'Świetna robota, $N! Przybiegł do mnie podekscytowany zwiadowca z raportem o twoich wyczynach. My w Lidze Aratoru jesteśmy bardzo zadowoleni!$b$bSzybko stajesz się $gmiejscowym bohaterem:miejscową bohaterką; wśród żołnierzy Ligi, a dzisiejszy czyn po raz kolejny potwierdza twoją nieskazitelną reputację.', 0),
(8115, 'koKR', 'Udało ci się! $GZdobyłeś:Zdobyłaś; wszystkie bazy! Dobra robota, $N!$b$bNiektórzy wątpili w twoje szanse, ale ja wiedziałem, że dasz radę. Dziękuję ci. Wiedz, że Liga Aratoru darzy cię wielkim szacunkiem, a Plugawiciele Porzuconych muszą drżeć na sam dźwięk twojego imienia!', 0),
(8120, 'koKR', 'Zwiadowca Plugawicieli przyniósł mi raport o twoim sukcesie, $N. Dobra robota.$b$bJak się przekonasz, aby wygrać bitwę o Kotlinę Aratorską, musimy być zawsze czujni i miażdżyć wszelkie próby ekspansji Przymierza. Rób tak, a nasze zwycięstwo jest pewne.', 0),
(8121, 'koKR', 'Dobra robota, $N! Twoje ostatnie działania w Kotlinie Aratorskiej były bardzo trudne, więc ich sukces zasługuje na tym większą pochwałę. Liga Aratoru musi się chwiać po ostatnich potyczkach w kotlinie – liże rany i, miejmy nadzieję, zastanawia się, czy warto tu walczyć.', 0),
(8122, 'koKR', 'Krzyki Przymierza, gdy ty i twoi towarzysze na nich uderzyliście, słychać było aż tutaj, $N. Niemal mi ich żal z powodu bólu i strachu, jaki zasialiście w ich szeregach. Niemal, ale nie całkiem.$b$bTwoja wartość dla Plugawicieli nie podlega dyskusji. Twoje czyny w Kotlinie Aratorskiej zrobiły ogromne wrażenie, a ich echo rozniosło się po komnatach Varimathrasa... i samej Mrocznej Pani.', 0),
(8124, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od siepacza po najwyższego wodza.', 0),
(8157, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od piechura po feldmarszałka.', 0),
(8158, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od piechura po feldmarszałka.', 0),
(8159, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od piechura po feldmarszałka.', 0),
(8163, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od siepacza po najwyższego wodza.', 0),
(8164, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od siepacza po najwyższego wodza.', 0),
(8165, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od siepacza po najwyższego wodza.', 0),
(8166, 'koKR', 'Dotarły do mnie wieści o twoich wyczynach w Kotlinie Aratorskiej, $N. Dobra robota! Skoro do naszej walki przyłączają się tacy jak ty, wierzę, że pewnego dnia odzyskamy nasze ojczyste ziemie.', 0),
(8167, 'koKR', 'Dotarły do mnie wieści o twoich wyczynach w Kotlinie Aratorskiej, $N. Dobra robota! Skoro do naszej walki przyłączają się tacy jak ty, wierzę, że pewnego dnia odzyskamy nasze ojczyste ziemie.', 0),
(8168, 'koKR', 'Dotarły do mnie wieści o twoich wyczynach w Kotlinie Aratorskiej, $N. Dobra robota! Skoro do naszej walki przyłączają się tacy jak ty, wierzę, że pewnego dnia odzyskamy nasze ojczyste ziemie.', 0),
(8169, 'koKR', 'Zwiadowca Plugawicieli przyniósł mi raport o twoim sukcesie, $N. Dobra robota.$b$bJak się przekonasz, aby wygrać bitwę o Kotlinę Aratorską, musimy być zawsze czujni i miażdżyć wszelkie próby ekspansji Przymierza. Rób tak, a nasze zwycięstwo jest pewne.', 0),
(8170, 'koKR', 'Zwiadowca Plugawicieli przyniósł mi raport o twoim sukcesie, $N. Dobra robota.$b$bJak się przekonasz, aby wygrać bitwę o Kotlinę Aratorską, musimy być zawsze czujni i miażdżyć wszelkie próby ekspansji Przymierza. Rób tak, a nasze zwycięstwo jest pewne.', 0),
(8171, 'koKR', 'Zwiadowca Plugawicieli przyniósł mi raport o twoim sukcesie, $N. Dobra robota.$b$bJak się przekonasz, aby wygrać bitwę o Kotlinę Aratorską, musimy być zawsze czujni i miażdżyć wszelkie próby ekspansji Przymierza. Rób tak, a nasze zwycięstwo jest pewne.', 0),
(8260, 'koKR', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Kotlinie Aratorskiej.$b$bW miarę jak będziesz się dalej wykazywać w Kotlinie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(8261, 'koKR', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Kotlinie Aratorskiej.$b$bW miarę jak będziesz się dalej wykazywać w Kotlinie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(8262, 'koKR', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Kotlinie Aratorskiej.$b$bW miarę jak będziesz się dalej wykazywać w Kotlinie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(8263, 'koKR', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Kotlinie Aratorskiej.$b$bW miarę jak będziesz się dalej wykazywać w Kotlinie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Szanowany, a bandaże – gdy osiągniesz poziom Czczony.', 0),
(8264, 'koKR', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Kotlinie Aratorskiej.$b$bW miarę jak będziesz się dalej wykazywać w Kotlinie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Szanowany, a bandaże – gdy osiągniesz poziom Czczony.', 0),
(8265, 'koKR', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Kotlinie Aratorskiej.$b$bW miarę jak będziesz się dalej wykazywać w Kotlinie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Szanowany, a bandaże – gdy osiągniesz poziom Czczony.', 0),
(8298, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od piechura po feldmarszałka.', 0),
(8300, 'koKR', 'Bardzo dobrze. Natychmiast przekażę je naszym kwatermistrzom, a do moich przełożonych trafi pochwała za twoje czyny.$B$BJeszcze raz dziękuję, $N. Twój wkład w naszą walkę dostrzegają wszyscy, od siepacza po najwyższego wodza.', 0),
(11732, 'koKR', 'Zbezcześć wielkie ognisko Przymierza na Wyżynach Aratorskich!', 0),
(11764, 'koKR', 'Zbezcześć wielkie ognisko Hordy na Wyżynach Aratorskich!', 0),
(11804, 'koKR', 'Uczcij płomień Wyżyn Aratorskich!', 0),
(11840, 'koKR', 'Uczcij płomień Wyżyn Aratorskich!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(639, 'koKR', '$GZnalazłeś:Znalazłaś; już pierwszy symbol? Najpewniej nosi go przy sobie któryś z agentów Syndykatu w Stromgardzie.', 0),
(640, 'koKR', 'Throm\'ka, $N. Zengu mówił, że potrzebujesz mojej pomocy?', 0),
(641, 'koKR', '$N! Masz drugi symbol?', 0),
(642, 'koKR', 'Ta grupa odłamków bardzo przypomina Odłamki Myzrael. Nie bije jednak od niej to samo poczucie bezpieczeństwa.', 0),
(643, 'koKR', 'Niełatwo będzie wytropić Zewa Męstwa, $N. Konno szybko przemierza okolicę. Mimo to musimy zdobyć jego symbol.', 0),
(644, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Czy ród Ignaeusa Trollbane\'a został przerwany?', 0),
(645, 'koKR', 'Ryty w kamieniu na płycie grobowca Trollbane\'a pasują do lśniących linii symbolu Ignaeusa...', 0),
(646, 'koKR', '$N! $GZdobyłeś:Zdobyłaś; miecz?', 0),
(651, 'koKR', 'To Kamień Wewnętrznego Spętania. Jest najsilniejszy z kamieni spętania i trzeba go otworzyć, by otworzyły się pozostałe.', 0),
(652, 'koKR', 'Zwornik jest naładowany ogromną energią geomantyczną.', 0),
(656, 'koKR', 'Odłamki Myzrael są teraz dziwnie ciche.', 0),
(662, 'koKR', 'Jak idzie misja poszukiwawcza, $N? Naprawdę musimy odzyskać te dzienniki i mapy z „Dziewiczego Szaleństwa” i „Ducha Srebrzystego Boru”.$b$bGdyby te informacje wpadły w ręce wroga, mistrz floty Morski Róg kazałby nam przejść po desce.$b$bO ile w ogóle wyplączemy się z tego bałaganu...', 0),
(664, 'koKR', 'Bah, może sam powinienem pójść wybić te nagowe szumowiny. Widać, że ty tego nie zrobisz.$B$BMoże znajdę ci jakieś druty do dziergania, żebyś $gmiał:miała; zajęcie.', 0),
(665, 'koKR', 'Nie czas na pogawędki! Gogle trzeba naładować mocą kamienia!', 0),
(666, 'koKR', 'Jak się sprawiły gogle? Wszystko działało jak należy? W razie potrzeby mogę je wyregulować.$b$bA, i będę potrzebował tych gogli z powrotem, kiedy skończysz. Jestem pewien, że kapitan O\'Breen znajdzie dla nich później mnóstwo zastosowań.', 0),
(668, 'koKR', 'Ahoj, $N. Co cię sprowadza na mostek?', 0),
(669, 'koKR', 'Co cię sprowadza do Łupieżczej Zatoki, $N?', 0),
(670, 'koKR', 'No i jak, zrobiło to wrażenie na Morskim Rogu? Założę się, że uśmiechnął się od ucha do ucha – od Łupieżczej Zatoki aż po Zapadkę.', 0),
(671, 'koKR', 'W moich żyłach wciąż płynie niegdyś przeklęta krew, $N. Jeśli ktoś... albo coś przyzywa demony, trzeba to powstrzymać.', 0),
(672, 'koKR', 'Stworzę amulet, który da Gor\'mulowi trochę siły raptorów. Może rozpali w nim jakiś płomień...', 0),
(673, 'koKR', 'Ogień w mojej krwi... rośnie z każdym dniem. Czarnoksiężnika trzeba powstrzymać.', 0),
(674, 'koKR', 'Jaka nadzieja, skoro ręka tchórza może zabić najpotężniejszego z potężnych? Jaka nadzieja, pytam cię!', 0),
(677, 'koKR', 'Jeśli jeszcze nie $gwykonałeś:wykonałaś; mojego zadania, to może jesteś tchórzem w sercu, a w wojnie żółtodziobem.', 0),
(678, 'koKR', 'Wahasz się. Dlaczego? Do tej pory $gokazałeś:okazałaś; wielką siłę, $N. Nie zawiedź mnie teraz.', 0),
(679, 'koKR', 'Widzę, że odwaga w końcu cię opuszcza. Zdaje się, że przeczucie mnie nie myliło: twoja siła to nic w porównaniu z twoimi przechwałkami.$b$bWróć do mnie, gdy bestia straci łeb, albo nie wracaj wcale.', 0),
(680, 'koKR', 'Or\'Kalara znajdziesz w pobliżu Wieży Aratoru. Jego śmierć zakończy ataki na Młotogród i ocali życie mojego męża.$B$BWidzę w twoich oczach, że uważasz mnie za słabą, a nawet za pozbawioną honoru, bo milczę. Pewnego dnia zrozumiesz, co to znaczy kochać tak jak ja. Może wtedy pojmiesz, że istnieje inny rodzaj siły i honoru.$B$BTymczasem zrób, o co proszę, i zabij Or\'Kalara.', 0),
(681, 'koKR', '$N, z każdą godziną nasza władza nad Stromgardem słabnie. Musisz się pośpieszyć, inaczej nasze miasto na pewno padnie.', 0),
(682, 'koKR', '$GOdzyskałeś:Odzyskałaś; jakieś odznaki Stromgardu, $N? Syndykat musi się nauczyć, że nie zarobi na naszych zmarłych.', 0),
(684, 'koKR', 'Witaj, $N. Masz dla mnie raport?', 0),
(685, 'koKR', 'Witaj. Masz raport do złożenia?', 0),
(691, 'koKR', 'Masz już jakieś postępy, $N?$B$B<Kryten czyta i robi notatki w dzienniku.>$B$BJeśli moje badania są trafne, kły można zdobyć od każdego trolla Suchokorych. Sakiewki lecznicze mają znachorzy Suchokorych, a najsilniejsi z łowców cieni Suchokorych powinni nosić specjalny nóż, który dostają po przejściu rytuału inicjacji. Nie da się stwierdzić, który łowca cieni ma nóż, dopóki nie stoczysz z nim walki.', 0),
(693, 'koKR', 'Naszym celem jest różdżka, $N. Na razie skup się na niej.', 0),
(694, 'koKR', '$N, witaj ponownie. $GZnalazłeś:Znalazłaś; już lazurowy agat?', 0),
(696, 'koKR', 'Zrób to, a Malin będzie z ciebie więcej niż zadowolony.', 0),
(701, 'koKR', 'Wszystko już przygotowałem, brakuje mi tylko serc raptorów.', 0),
(702, 'koKR', 'Znowu $gwróciłeś:wróciłaś;? Doprawdy, niczego bardziej teraz nie pragnę niż kolejnej porcji litości Tor\'gana.$B$BCo tym razem dla mnie masz? Może kawałek jaskrawego sznurka? Albo kawał liny, by skończyć tę moją niedolę...', 0),
(5144, 'koKR', 'Wytwarzanie tego rodzaju skórzanych pancerzy wymaga cierpliwości i oddania. Gdy już zwiążesz swój los z żywiołami, nie ma odwrotu. Przynieś mi dowód, że jesteś tego $ggodzien:godna;, i zaczniemy.', 0),
(5146, 'koKR', 'Wytwarzanie tego rodzaju skórzanych pancerzy wymaga cierpliwości i oddania. Gdy już zwiążesz swój los z żywiołami, nie ma odwrotu. Przynieś mi dowód, że jesteś tego $ggodzien:godna;, i zaczniemy.', 0),
(6622, 'koKR', 'Cudowna robota, $gdoktorze:pani doktor;. Po prostu cudowna.', 0),
(6624, 'koKR', 'Cudowna robota, $gdoktorze:pani doktor;. Po prostu cudowna.', 0),
(8081, 'koKR', '$N, Liga Aratoru ma dla ciebie stałe zadanie: wróć do Kotliny Aratorskiej, zdobądź więcej skrzyń zasobów i przynieś je do mnie.', 0),
(8124, 'koKR', '$N, Plugawiciele mają dla ciebie stałe zadanie: wróć do Kotliny Aratorskiej, zdobądź więcej skrzyń zasobów i przynieś je do mnie.', 0),
