INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2487, 0, 'koKR', 'Ach, poczuj tę wspaniałą słoną bryzę! Zawsze miło wrócić do naszego macierzystego portu w Łupieżczej Zatoce.', 0),
(2497, 0, 'koKR', 'Hę? Nimboya jest ci do czegoś potrzebny?', 0),
(2706, 0, 'koKR', 'Dzięki wodzowi nawet tu, w ruinach naszego dawnego więzienia, tli się jeszcze nadzieja, a Horda odradza się na nowo.', 0),
(2713, 1, 'koKR', 'Na tej drewnianej tablicy wiszą niedbale sporządzone listy gończe.', 0),
(138492, 1, 'koKR', 'Te odłamki lśnią nienaturalnym blaskiem. Wyraźnie kryją w sobie głęboką moc.', 0);
