INSERT INTO `trainer_locale` (`Id`, `locale`, `Greeting_lang`, `VerifiedBuild`) VALUES
(93, 'koKR', 'Nie ma lepszego przysmaku niż skrzydło sępa z grilla.', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(732, 'koKR', '%s przeszukuje czaszki...', '', 0),
(733, 'koKR', '%s szuka dalej, wkładając kolejne czaszki do skrzyni.', '', 0),
(734, 'koKR', 'Skończyłem oglądać czaszki, $n, i ulżyło mi. Nie ma wśród nich Yenniku...', '', 0),
(735, 'koKR', 'Ach, dobrze, $n. Zobaczmy teraz, jaką opowieść snują te głowy...', '', 0),
(736, 'koKR', '%s zaczyna intonować zaklęcie...', '', 0),
(740, 'koKR', 'Gotowe, $n. Możesz teraz porozmawiać z wodzem Krwawych Skalpów i jego znachorem.', '', 0),
(782, 'koKR', 'Wciąż ani śladu ostatniej dostawy materiałów wybuchowych.', '', 0),
(783, 'koKR', 'Na zachodzie też ani śladu ostatniej dostawy materiałów wybuchowych. Gdzie się podziewają te obiboki?', '', 0),
(784, 'koKR', 'Ten most powinien już dawno leżeć w gruzach. Ileż tym leniwym łajzom zajmuje droga tutaj z Wyżyn!', '', 0),
(798, 'koKR', 'Łatwiej, niż się spodziewałem... Symbol Thoradina znów jest cały.', '', 0),
(799, 'koKR', 'Obym mógł wiecznie pławić się w twoim cieniu!', '', 0),
(800, 'koKR', 'Panie, twoja mądrość dorównuje tylko twojej ogromności!', '', 0),
(801, 'koKR', 'Gdybym miał miedziaka za każdy twój wielki czyn, byłbym bogatym koboldem!', '', 0),
(802, 'koKR', 'Ochronisz nas przed złą władczynią, tak!', '', 0),
(803, 'koKR', 'Och, chwała! Twoja czujność trzyma Myzrael głęboko pod ziemią!', '', 0),
(804, 'koKR', 'Moim jedynym pragnieniem jest służyć ci, o wielki, aż zginę pod twoją stopą!', '', 0),
(805, 'koKR', 'Twoja siła pochodzi z gór. Twój wdzięk – z wiatrów!', '', 0),
(806, 'koKR', 'Bolą mnie stopy...', '', 0),
(807, 'koKR', 'Giń! Nie uwolnisz Myzrael!', '', 0),
(808, 'koKR', 'Wielki cię zmiażdży!', '', 0),
(809, 'koKR', 'Nie jesteś trochę za $gniski:niska; jak na swój gatunek?', '', 0),
(810, 'koKR', 'Moje życie nic nie znaczy! Liczy się tylko nasze święte zadanie!', '', 0),
(811, 'koKR', 'Jeśli zamierzasz uwolnić Myzrael, pożałujesz!', '', 0),
(812, 'koKR', 'Trzymajcie się, bracia. I nie bójcie się! Rozmiar jest po naszej stronie!', '', 0),
(814, 'koKR', 'Masz! Suchowąsy zwyciężą!', '', 0),
(815, 'koKR', 'Nie! Zostaw nas! Nie możemy zawieść w naszym zadaniu!', '', 0),
(845, 'koKR', 'Dobrze, $n. Chodź za mną do jaskini, gdzie spróbuję przelać moc runicznego kamienia do tych gogli.', '', 0),
(846, 'koKR', 'Odkryłem tę jaskinię pierwszego dnia po przybyciu tutaj. Wierzę, że energię tego kamienia można wykorzystać na naszą korzyść.', '', 0),
(847, 'koKR', 'Zacznę czerpać energię z kamienia. Twoje zadanie, $n, to mnie bronić. To miejsce jest przeklęte... uwierz mi.', '', 0),
(848, 'koKR', '%s zaczyna majstrować przy goglach przed kamieniem.', '', 0),
(849, 'koKR', 'Prawie gotowe! Jeszcze tylko chwila!', '', 0),
(850, 'koKR', 'Udało się! Przelałem moc kamienia do gogli! Wynośmy się stąd!', '', 0),
(851, 'koKR', 'Uff! Dobrze, że wróciliśmy z tej upiornej jaskini.', '', 0),
(857, 'koKR', 'Czekaj, $n!!! Wygląda na to, że będziemy tu potrzebować pomocy...', '', 0),
(858, 'koKR', 'Pomocy!! Mówiłem, że to miejsce jest przeklęte!', '', 0),
(859, 'koKR', 'Pomocy!!! Zdejmijcie ze mnie te stwory, żebym mógł skończyć pracę!', '', 0),
(861, 'koKR', 'Cóż to za moc przepływa przeze mnie? Czy to moc szamanizmu, o której mówił Tor\'gan...?', '', 0),
(862, 'koKR', 'Niesamowite! Czuję się... odnowiony. Wraca mi siła!', '', 0),
(863, 'koKR', 'Jeśli tylko teraz ich powstrzymamy, jestem pewien, że będziemy bezpieczni.', '', 0),
(889, 'koKR', '%s wręcza świecące gogle doktorowi Draxlegauge\'owi.', '', 0),
(890, 'koKR', 'Doktor Draxlegauge przekaże ci dalsze instrukcje, $n. Wielkie dzięki za pomoc!', '', 0),
(895, 'koKR', 'Nigdy nie powstrzymasz Porzuconych. Mroczna Pani sprawi, że będziesz cierpieć.', '', 0),
(896, 'koKR', 'Daję ci słowo, że znajdę zastosowanie dla twojego ciała, gdy już cię zabiję.', '', 0),
(1020, 'koKR', '%s patrzy, jak jego krew zaczyna się burzyć, a przebiegłość raptora przenika go na wskroś.', '', 0),
(5550, 'koKR', 'Nie przejmuj się Skuertem, $n. Nie chce być niegrzeczny, po prostu jest strasznie zajęty. Zanim skończy zwiad, może zajmiemy się czymś bardziej pożytecznym?', '', 0),
(6292, 'koKR', 'Duchy powiedziały mi, że przyjdziesz, że z jakiegoś powodu będziesz mnie szukać, ale że nawet ty możesz tego powodu nie znać. Więc wiesz, dlaczego tu jesteś?', '', 0),
(6372, 'koKR', 'Wszyscy na stanowiska bojowe! Nadciągają nagi!', '', 0),
(10382, 'koKR', 'Liga Aratoru przysięgła odbić Arator dla ludzi ze Stromgardu i dla Przymierza. To zacięta bitwa, ale warta stoczenia.', '', 0),
(10383, 'koKR', '', 'Aby wygrać tę wojnę, nie możemy siedzieć bezczynnie i czekać, aż zaleje nas fala. Musimy uderzyć mocno i szybko, inaczej Arator już nigdy nie będzie nasz.', 0),
(10431, 'koKR', '', 'Nie możemy pozwolić, by Przymierze poszerzało swoje wpływy w Aratorze! Nawet ich maleńki Punkt Schronienia może pewnego dnia urosnąć na tyle, by nam zagrozić.', 0),
(10432, 'koKR', 'Bitwa o Kotlinę Aratorską to walka o zasoby. Drewno, ruda, żywność... wszystko to jest potrzebne, by dobrze prowadzić wojnę.$B$BOdcięcie wrogów od zaopatrzenia jest równie skuteczne, co zabicie ich na polu bitwy.', '', 0),
(10574, 'koKR', 'Dziękuję za propozycję, $N. Niestety nie masz jeszcze dość doświadczenia, by stawić czoła niebezpieczeństwom Kotliny Aratorskiej.', 'Dziękuję za propozycję, $N. Niestety nie masz jeszcze dość doświadczenia, by stawić czoła niebezpieczeństwom Kotliny Aratorskiej.', 0),
(17745, 'koKR', '', 'Ruszaj, $n, do Kotliny Aratorskiej! Zabijaj, ZABIJAJ, jak jeszcze nigdy nie $gzabijałeś:zabijałaś;!', 0),
(18917, 'koKR', 'Chcę zapomnieć garbarstwo żywiołów!', 'Chcę zapomnieć garbarstwo żywiołów!', 0),
(18923, 'koKR', 'Zapomnienie garbarstwa żywiołów to nie jest decyzja, którą podejmuje się lekko. Jeśli z niego zrezygnujesz, zapomnisz również wszystkie receptury wymagające garbarstwa żywiołów!', 'Zapomnienie garbarstwa żywiołów to nie jest decyzja, którą podejmuje się lekko. Jeśli z niego zrezygnujesz, zapomnisz również wszystkie receptury wymagające garbarstwa żywiołów!', 0),
(18969, 'koKR', 'Czy na pewno chcesz zapomnieć swoją specjalizację garbarską i utracić wszystkie powiązane z nią receptury?', 'Czy na pewno chcesz zapomnieć swoją specjalizację garbarską i utracić wszystkie powiązane z nią receptury?', 0),
(23459, 'koKR', 'Wszystko idzie zgodnie z planem, lordzie Sokoli Herbie. Zapewniam, że to tylko kwestia czasu.', 'Wszystko idzie zgodnie z planem, lordzie Sokoli Herbie. Zapewniam, że to tylko kwestia czasu.', 0),
(23460, 'koKR', 'Zakładam, że przychodzisz z dobrymi wieściami?', 'Zakładam, że przychodzisz z dobrymi wieściami?', 0),
(42912, 'koKR', 'Trolle z Cierniodławów nie przepadają za nami, Mrocznymi Włóczniami. Mnie tam żadne Krwawe Skalpy ani Rozłupywacze Czaszek nie straszne, ale i tak... za wysokimi murami Grom\'gol czuję się bezpiecznie.', '', 0),
(43587, 'koKR', 'Witaj w Łupieżczej Zatoce.', '', 0);
